#pragma once
#include "../Runtime/BackgroundHostProcess.h"

namespace coincide::background_host_fixture {
struct State {unsigned factories{},sends{},steers{},queues{},responses{},interrupts{},shutdowns{},edits{},removes{},pauses{},resumes{},refreshes{};bool busy{},paused{true},controls{true},emit_shutdown_event{},emit_started{},early_failure{};std::string input_id;std::vector<AgentQueuedTurn> pending;std::vector<SessionEvent> events;std::function<void()> before_delivery;};
class Session final:public AgentSession {
    std::shared_ptr<State> state_;
public:
    explicit Session(std::shared_ptr<State> state):state_(std::move(state)){++state_->factories;}
    bool send(CodexTurn input)override{if(state_->before_delivery)state_->before_delivery();++state_->sends;if(state_->busy)return false;state_->busy=true;if(state_->early_failure){state_->events.push_back({SessionEvent::Kind::error,state_->input_id,"synthetic setup refused","fixture_setup_failed"});state_->events.push_back({SessionEvent::Kind::completed,"","",""});state_->busy=false;return true;}if(state_->emit_started)state_->events.push_back({SessionEvent::Kind::started,state_->input_id,"synthetic started",""});state_->events.push_back({SessionEvent::Kind::input,state_->input_id,input.text,"synthetic input acknowledged"});if(input.text!="wait"){state_->events.push_back({SessionEvent::Kind::text_complete,"fixture-reply","synthetic reply",""});state_->events.push_back({SessionEvent::Kind::completed,"","",""});state_->busy=false;}return true;}
    bool busy()const noexcept override{return state_->busy;}void interrupt()noexcept override{++state_->interrupts;state_->busy=false;state_->paused=true;}
    bool refresh_models()override{++state_->refreshes;state_->events.push_back({SessionEvent::Kind::models,"",R"({"data":[{"id":"synthetic-model","displayName":"Fixture model"}]})",""});return true;}bool queue(CodexTurn input,std::string id)override{if(state_->before_delivery)state_->before_delivery();++state_->queues;state_->pending.push_back({id,input});state_->events.push_back({SessionEvent::Kind::queued,std::move(id),input.text,"synthetic queued"});return true;}
    std::vector<AgentQueuedTurn> queued()const override{return state_->pending;}std::size_t queued_count()const override{return state_->pending.size();}bool queue_paused()const override{return state_->paused;}bool remove_queued(const std::string& id)override{++state_->removes;const auto at=std::find_if(state_->pending.begin(),state_->pending.end(),[&](const auto& value){return value.id==id;});if(at==state_->pending.end())return false;state_->pending.erase(at);state_->events.push_back({SessionEvent::Kind::queue_changed,id,"","removed"});return true;}bool resume_queue()override{++state_->resumes;if(state_->pending.empty())return false;state_->paused=false;state_->events.push_back({SessionEvent::Kind::queue_changed,"","","resumed"});return true;}
    bool pause_queue()override{++state_->pauses;if(!state_->controls)return false;state_->paused=true;state_->events.push_back({SessionEvent::Kind::queue_changed,"","","paused"});return true;}
    bool edit_queued(const std::string& id,CodexTurn turn)override{++state_->edits;if(!state_->controls)return false;const auto at=std::find_if(state_->pending.begin(),state_->pending.end(),[&](const auto& value){return value.id==id;});if(at==state_->pending.end())return false;at->turn=std::move(turn);state_->events.push_back({SessionEvent::Kind::queue_changed,id,at->turn.text,"edited"});return true;}
    bool steer(CodexTurn,std::string)override{if(state_->before_delivery)state_->before_delivery();++state_->steers;return state_->busy;}
    void respond(std::string,std::string)override{++state_->responses;}
    std::vector<SessionEvent> take_events()override{auto result=std::move(state_->events);state_->events.clear();return result;}
    void close()noexcept override{state_->busy=false;}void shutdown()noexcept override{++state_->shutdowns;state_->busy=false;state_->paused=true;if(state_->emit_shutdown_event){state_->emit_shutdown_event=false;state_->events.push_back({SessionEvent::Kind::status,"","synthetic final status","fixture_shutdown"});}}
};
inline background_host::Command start(const std::filesystem::path& root){using namespace background_host;Command value;value.operation=Operation::start;value.key=checked({"{59f31ac2-5a6a-48d6-98d0-65ea9239edc7}","codex"});value.epoch=new_guid();value.launch.executable=current_image();value.launch.cwd=root;value.launch.profile_directory=root;value.launch.arguments={L"synthetic-provider"};return value;}
inline background_host::Command input(const background_host::Command& start,std::string text="fixture turn",background_host::Operation operation=background_host::Operation::send){background_host::Command value;value.operation=operation;value.key=start.key;value.epoch=start.epoch;value.delivery_id=background_host::new_guid();value.input.text=std::move(text);value.input.cwd=winrt::to_string(start.launch.cwd.wstring());return value;}
} // namespace coincide::background_host_fixture
